using System;
using System.Buffers;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Threading.Tasks;

namespace SecureMessaging
{
    /// <summary>
    /// Implements a secure message framing protocol for encrypted communication.
    /// Messages are chunked, individually encrypted with AES-256-GCM, and framed
    /// with length-prefixed headers for reliable transport.
    /// </summary>
    public sealed class SecureFrameProcessor : IDisposable
    {
        private const int AesKeySize = 32;
        private const int GcmNonceSize = 12;
        private const int GcmTagSize = 16;
        private const int FrameHeaderSize = 8; // 4 bytes chunk count + 4 bytes flags
        private const int ChunkHeaderSize = 4; // 4 bytes payload length
        private const int MaxChunkPayload = 65536;
        private const int MaxMessageSize = 128 * 1024 * 1024; // 128 MB

        private readonly byte[] _masterKey;
        private readonly SemaphoreSlim _lock = new SemaphoreSlim(1, 1);
        private bool _disposed;

        public SecureFrameProcessor(byte[] masterKey)
        {
            if (masterKey == null || masterKey.Length != AesKeySize)
                throw new ArgumentException("Master key must be 32 bytes", nameof(masterKey));
            _masterKey = new byte[AesKeySize];
            Buffer.BlockCopy(masterKey, 0, _masterKey, 0, AesKeySize);
        }

        /// <summary>
        /// Derives a per-message encryption key using HKDF with a random salt.
        /// </summary>
        private (byte[] key, byte[] salt) DeriveMessageKey(byte[] context)
        {
            byte[] salt = new byte[32];
            RandomNumberGenerator.Fill(salt);
            byte[] prk = HMACSHA256Hash(_masterKey, salt);
            byte[] info = Encoding.UTF8.GetBytes("SecureFrame_v1_MessageKey");
            byte[] combined = new byte[info.Length + context.Length];
            Buffer.BlockCopy(info, 0, combined, 0, info.Length);
            Buffer.BlockCopy(context, 0, combined, info.Length, context.Length);
            byte[] key = HMACSHA256Hash(prk, combined);
            return (key, salt);
        }

        private static byte[] HMACSHA256Hash(byte[] key, byte[] data)
        {
            using var hmac = new HMACSHA256(key);
            return hmac.ComputeHash(data);
        }

        /// <summary>
        /// Encrypts a single chunk using AES-256-GCM with a fresh nonce.
        /// Returns: nonce(12) || tag(16) || ciphertext
        /// </summary>
        private byte[] EncryptChunk(byte[] key, byte[] plaintext, int offset, int length)
        {
            byte[] nonce = new byte[GcmNonceSize];
            RandomNumberGenerator.Fill(nonce);
            byte[] ciphertext = new byte[length];
            byte[] tag = new byte[GcmTagSize];

            using var aes = new AesGcm(key, GcmTagSize);
            aes.Encrypt(nonce, plaintext.AsSpan(offset, length), ciphertext, tag);

            byte[] result = new byte[GcmNonceSize + GcmTagSize + length];
            Buffer.BlockCopy(nonce, 0, result, 0, GcmNonceSize);
            Buffer.BlockCopy(tag, 0, result, GcmNonceSize, GcmTagSize);
            Buffer.BlockCopy(ciphertext, 0, result, GcmNonceSize + GcmTagSize, length);
            return result;
        }

        /// <summary>
        /// Decrypts a single chunk. Input format: nonce(12) || tag(16) || ciphertext
        /// </summary>
        private byte[] DecryptChunk(byte[] key, byte[] encryptedChunk)
        {
            if (encryptedChunk.Length < GcmNonceSize + GcmTagSize)
                throw new CryptographicException("Invalid chunk: too short");

            int ciphertextLen = encryptedChunk.Length - GcmNonceSize - GcmTagSize;
            byte[] nonce = new byte[GcmNonceSize];
            byte[] tag = new byte[GcmTagSize];
            byte[] ciphertext = new byte[ciphertextLen];
            byte[] plaintext = new byte[ciphertextLen];

            Buffer.BlockCopy(encryptedChunk, 0, nonce, 0, GcmNonceSize);
            Buffer.BlockCopy(encryptedChunk, GcmNonceSize, tag, 0, GcmTagSize);
            Buffer.BlockCopy(encryptedChunk, GcmNonceSize + GcmTagSize, ciphertext, 0, ciphertextLen);

            using var aes = new AesGcm(key, GcmTagSize);
            aes.Decrypt(nonce, ciphertext, tag, plaintext);
            return plaintext;
        }

        /// <summary>
        /// Calculates the total buffer size needed for the framed encrypted message.
        /// Each chunk expands by GcmNonceSize + GcmTagSize + ChunkHeaderSize bytes.
        /// Uses checked arithmetic to prevent integer overflow.
        /// </summary>
        private int CalculateFrameBufferSize(int messageLength, int chunkCount)
        {
            // Frame header + salt(32) + per-chunk overhead
            // Per chunk: ChunkHeaderSize(4) + GcmNonceSize(12) + GcmTagSize(16) + payload
            int perChunkOverhead = ChunkHeaderSize + GcmNonceSize + GcmTagSize;

            // Calculate total size with checked arithmetic to prevent overflow
            int totalOverhead = checked(FrameHeaderSize + 32 + (perChunkOverhead * chunkCount));
            return checked(totalOverhead + messageLength);
        }

        /// <summary>
        /// Frames and encrypts a message, splitting into chunks for streaming.
        /// </summary>
        public async Task<byte[]> FrameMessageAsync(byte[] message, byte[] context, CancellationToken ct = default)
        {
            ObjectDisposedException.ThrowIf(_disposed, this);
            if (message == null) throw new ArgumentNullException(nameof(message));
            if (message.Length > MaxMessageSize)
                throw new ArgumentException($"Message exceeds maximum size of {MaxMessageSize}");
            if (context == null || context.Length == 0)
                throw new ArgumentException("Context must not be empty", nameof(context));

            await _lock.WaitAsync(ct).ConfigureAwait(false);
            try
            {
                var (key, salt) = DeriveMessageKey(context);
                try
                {
                    int chunkCount = (message.Length + MaxChunkPayload - 1) / MaxChunkPayload;
                    if (chunkCount == 0) chunkCount = 1;

                    int bufferSize = CalculateFrameBufferSize(message.Length, chunkCount);
                    byte[] frame = new byte[bufferSize];
                    int writePos = 0;

                    // Write frame header
                    BitConverter.TryWriteBytes(frame.AsSpan(writePos), chunkCount);
                    writePos += 4;
                    BitConverter.TryWriteBytes(frame.AsSpan(writePos), 0); // flags reserved
                    writePos += 4;

                    // Write salt
                    Buffer.BlockCopy(salt, 0, frame, writePos, 32);
                    writePos += 32;

                    // Encrypt and write each chunk
                    for (int i = 0; i < chunkCount; i++)
                    {
                        int chunkOffset = i * MaxChunkPayload;
                        int chunkLen = Math.Min(MaxChunkPayload, message.Length - chunkOffset);

                        byte[] encryptedChunk = EncryptChunk(key, message, chunkOffset, chunkLen);

                        // Write chunk header (encrypted chunk length)
                        BitConverter.TryWriteBytes(frame.AsSpan(writePos), encryptedChunk.Length);
                        writePos += ChunkHeaderSize;

                        // Write encrypted chunk data
                        Buffer.BlockCopy(encryptedChunk, 0, frame, writePos, encryptedChunk.Length);
                        writePos += encryptedChunk.Length;
                    }

                    // Return only the used portion
                    byte[] result = new byte[writePos];
                    Buffer.BlockCopy(frame, 0, result, 0, writePos);
                    return result;
                }
                finally
                {
                    CryptographicOperations.ZeroMemory(key);
                }
            }
            finally
            {
                _lock.Release();
            }
        }

        /// <summary>
        /// Parses and decrypts a framed message from a stream.
        /// Validates frame integrity before processing.
        /// </summary>
        public async Task<byte[]> ParseFrameAsync(Stream input, byte[] context, CancellationToken ct = default)
        {
            ObjectDisposedException.ThrowIf(_disposed, this);
            if (input == null) throw new ArgumentNullException(nameof(input));
            if (context == null || context.Length == 0)
                throw new ArgumentException("Context must not be empty", nameof(context));

            await _lock.WaitAsync(ct).ConfigureAwait(false);
            try
            {
                // Read frame header
                byte[] header = new byte[FrameHeaderSize];
                await ReadExactAsync(input, header, ct).ConfigureAwait(false);

                int chunkCount = BitConverter.ToInt32(header, 0);
                int flags = BitConverter.ToInt32(header, 4);

                if (chunkCount <= 0 || chunkCount > (MaxMessageSize / 1024) + 1)
                    throw new InvalidDataException("Invalid chunk count in frame header");

                // Read salt
                byte[] salt = new byte[32];
                await ReadExactAsync(input, salt, ct).ConfigureAwait(false);

                // Derive key
                byte[] prk = HMACSHA256Hash(_masterKey, salt);
                byte[] info = Encoding.UTF8.GetBytes("SecureFrame_v1_MessageKey");
                byte[] combined = new byte[info.Length + context.Length];
                Buffer.BlockCopy(info, 0, combined, 0, info.Length);
                Buffer.BlockCopy(context, 0, combined, info.Length, context.Length);
                byte[] key = HMACSHA256Hash(prk, combined);

                try
                {
                    // Calculate expected maximum output size with overflow protection
                    long maxOutputSizeLong = (long)chunkCount * MaxChunkPayload;
                    int maxOutputSize = (int)Math.Min(maxOutputSizeLong, MaxMessageSize);

                    using var outputStream = new MemoryStream(maxOutputSize);

                    for (int i = 0; i < chunkCount; i++)
                    {
                        ct.ThrowIfCancellationRequested();

                        // Read chunk header
                        byte[] chunkHeader = new byte[ChunkHeaderSize];
                        await ReadExactAsync(input, chunkHeader, ct).ConfigureAwait(false);
                        int encChunkLen = BitConverter.ToInt32(chunkHeader, 0);

                        if (encChunkLen <= 0 || encChunkLen > MaxChunkPayload + GcmNonceSize + GcmTagSize)
                            throw new InvalidDataException($"Invalid encrypted chunk length: {encChunkLen}");

                        // Read encrypted chunk
                        byte[] encChunk = new byte[encChunkLen];
                        await ReadExactAsync(input, encChunk, ct).ConfigureAwait(false);

                        // Decrypt
                        byte[] plainChunk = DecryptChunk(key, encChunk);
                        await outputStream.WriteAsync(plainChunk, ct).ConfigureAwait(false);

                        if (outputStream.Length > MaxMessageSize)
                            throw new InvalidDataException("Decrypted message exceeds maximum size");
                    }

                    return outputStream.ToArray();
                }
                finally
                {
                    CryptographicOperations.ZeroMemory(key);
                }
            }
            finally
            {
                _lock.Release();
            }
        }

        /// <summary>
        /// Processes a batch of messages, allocating a combined output buffer.
        /// Used for bulk operations where multiple messages share the same context.
        /// </summary>
        public async Task<byte[]> ProcessBatchAsync(byte[][] messages, byte[] context, CancellationToken ct = default)
        {
            ObjectDisposedException.ThrowIf(_disposed, this);
            if (messages == null) throw new ArgumentNullException(nameof(messages));
            if (messages.Length == 0) throw new ArgumentException("No messages to process");
            if (messages.Length > 1024)
                throw new ArgumentException("Batch size exceeds maximum of 1024");

            // Validate individual messages
            for (int i = 0; i < messages.Length; i++)
            {
                if (messages[i] == null)
                    throw new ArgumentNullException($"messages[{i}]");
                if (messages[i].Length > MaxMessageSize)
                    throw new ArgumentException($"Message {i} exceeds maximum size");
            }

            // Calculate total output buffer size with overflow-safe arithmetic
            long totalSize = 0;
            int[] frameSizes = new int[messages.Length];
            for (int i = 0; i < messages.Length; i++)
            {
                int msgLen = messages[i].Length;
                int chunks = (msgLen + MaxChunkPayload - 1) / MaxChunkPayload;
                if (chunks == 0) chunks = 1;
                frameSizes[i] = CalculateFrameBufferSize(msgLen, chunks);
                totalSize += 4L + frameSizes[i]; // 4 byte length prefix per message
            }

            if (totalSize > int.MaxValue)
                throw new InvalidOperationException("Batch too large for single buffer");

            byte[] batchBuffer = new byte[(int)totalSize];
            int batchPos = 0;

            for (int i = 0; i < messages.Length; i++)
            {
                ct.ThrowIfCancellationRequested();
                byte[] framed = await FrameMessageAsync(messages[i], context, ct).ConfigureAwait(false);

                // Write length prefix
                BitConverter.TryWriteBytes(batchBuffer.AsSpan(batchPos), framed.Length);
                batchPos += 4;

                // Write framed message
                Buffer.BlockCopy(framed, 0, batchBuffer, batchPos, framed.Length);
                batchPos += framed.Length;
            }

            byte[] result = new byte[batchPos];
            Buffer.BlockCopy(batchBuffer, 0, result, 0, batchPos);
            return result;
        }

        /// <summary>
        /// Parses a batch of framed messages from a buffer.
        /// Allocates output based on declared sizes in the frame headers.
        /// </summary>
        public async Task<byte[][]> ParseBatchAsync(byte[] batchData, byte[] context, CancellationToken ct = default)
        {
            ObjectDisposedException.ThrowIf(_disposed, this);
            if (batchData == null) throw new ArgumentNullException(nameof(batchData));
            if (batchData.Length < 4)
                throw new InvalidDataException("Batch data too short");

            var results = new System.Collections.Generic.List<byte[]>();
            int readPos = 0;

            while (readPos < batchData.Length - 3)
            {
                ct.ThrowIfCancellationRequested();

                if (readPos + 4 > batchData.Length)
                    break;

                int frameLen = BitConverter.ToInt32(batchData, readPos);
                readPos += 4;

                if (frameLen <= 0 || frameLen > batchData.Length - readPos)
                    throw new InvalidDataException($"Invalid frame length: {frameLen}");

                using var frameStream = new MemoryStream(batchData, readPos, frameLen, writable: false);
                byte[] decrypted = await ParseFrameAsync(frameStream, context, ct).ConfigureAwait(false);
                results.Add(decrypted);
                readPos += frameLen;

                if (results.Count > 1024)
                    throw new InvalidDataException("Too many messages in batch");
            }

            return results.ToArray();
        }

        private static async Task ReadExactAsync(Stream stream, byte[] buffer, CancellationToken ct)
        {
            int totalRead = 0;
            while (totalRead < buffer.Length)
            {
                int read = await stream.ReadAsync(buffer.AsMemory(totalRead), ct).ConfigureAwait(false);
                if (read == 0)
                    throw new EndOfStreamException("Unexpected end of stream while reading frame");
                totalRead += read;
            }
        }

        public void Dispose()
        {
            if (!_disposed)
            {
                _disposed = true;
                CryptographicOperations.ZeroMemory(_masterKey);
                _lock.Dispose();
            }
        }
    }
}
